# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/tasks/create-client-application.yml
#   step   : "Create Client Application" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
#
# Inputs (environment):
#   MDF_API_INSTANCE_ID          <- ${{ parameters.apiInstanceId }}  [default: (empty)]
#   MDF_BEARER_TOKEN             <- ${{ parameters.bearerToken }}  [required]
#   MDF_BG_ID                    <- ${{ parameters.bgId }}  [default: $(BG_ID)]
#   MDF_CLIENT_APPLICATION_NAME  <- ${{ parameters.clientApplicationName }}  [required]
# Outputs: CLIENT_APP_ID (output), APP_CLIENT_ID (secret output), APP_CLIENT_SECRET (secret output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_API_INSTANCE_ID=}"
: "${MDF_BEARER_TOKEN?MDF_BEARER_TOKEN is required (Azure parameter bearerToken)}"
: "${MDF_BG_ID=}"
: "${MDF_CLIENT_APPLICATION_NAME?MDF_CLIENT_APPLICATION_NAME is required (Azure parameter clientApplicationName)}"

# >>> extracted body
BG_ID="${MDF_BG_ID}"
API_INSTANCE_ID="${MDF_API_INSTANCE_ID}"
CLIENT_APP_NAME=$(echo "${MDF_CLIENT_APPLICATION_NAME}" | tr '[:upper:]' '[:lower:]')

echo "[DEBUG] ============================================"
echo "[DEBUG] CREATE CLIENT APPLICATION"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   apiInstanceId=$API_INSTANCE_ID"
echo "[DEBUG]   clientApplicationName=${MDF_CLIENT_APPLICATION_NAME}"
echo "[DEBUG]   CLIENT_APP_NAME (lowercase)=$CLIENT_APP_NAME"
echo "[DEBUG] ============================================"
echo "Creating client application: $CLIENT_APP_NAME"

# Exchange requires the application to target an API instance (apiInstanceId).
APP_URL="https://anypoint.mulesoft.com/exchange/api/v1/organizations/${BG_ID}/applications"
if [[ -n "$API_INSTANCE_ID" ]]; then
  APP_URL="${APP_URL}?apiInstanceId=${API_INSTANCE_ID}"
else
  ci_log_warning "apiInstanceId not provided. Exchange may reject the request (a target apiInstanceId or groupInstanceId is required)."
fi
echo "[DEBUG] Create client app URL: $APP_URL"

json_payload=$(jq -n \
  --arg name "$CLIENT_APP_NAME" \
  '{
    name: $name,
    redirectUri: [],
    grantTypes: ["client_credentials"],
    apiEndpoints: false
  }')

create_response=$(curl -i -s --location \
  "$APP_URL" \
  --header "Content-Type: application/json" \
  --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
  --data "$json_payload")

HTTP_STATUS=$(echo "$create_response" | head -n 1 | awk '{print $2}')
BODY=$(echo "$create_response" | sed -n '/^\r\{0,1\}$/,$p' | tail -n +2)

echo "[DEBUG] Create client app response status: $HTTP_STATUS"
echo "[DEBUG] Create client app response body: $BODY"

if [[ "$HTTP_STATUS" == "201" ]]; then
  echo "Client application created successfully."
  client_app_id=$(echo "$BODY" | jq -r '.id')
  client_id=$(echo "$BODY" | jq -r '.clientId')
  client_secret=$(echo "$BODY" | jq -r '.clientSecret')
  echo "[DEBUG] New client app: id=$client_app_id, clientId=${client_id:0:8}***"

elif [[ "$HTTP_STATUS" == "409" ]]; then
  echo "Client application already exists. Fetching details..."
  echo "[DEBUG] 409 — fetching existing client app by name=$CLIENT_APP_NAME"

  get_response=$(curl -s --request GET \
    --url "https://anypoint.mulesoft.com/apiplatform/repository/v2/organizations/${BG_ID}/applications?query=${CLIENT_APP_NAME}&targetAdminSite=true" \
    --header "Authorization: Bearer ${MDF_BEARER_TOKEN}")

  client_app_id=$(echo "$get_response" | jq -r --arg name "$CLIENT_APP_NAME" '.applications[] | select(.name == $name) | .id')
  client_id=$(echo "$get_response" | jq -r --arg name "$CLIENT_APP_NAME" '.applications[] | select(.name == $name) | .clientId')
  client_secret=$(echo "$get_response" | jq -r --arg name "$CLIENT_APP_NAME" '.applications[] | select(.name == $name) | .clientSecret')

else
  ci_log_error "Client application creation failed. Status: $HTTP_STATUS"
  echo "Response: $BODY"
  exit 1
fi

echo "Client App ID: $client_app_id"
echo "[DEBUG] Final: CLIENT_APP_ID=$client_app_id"
ci_set_var CLIENT_APP_ID "$client_app_id"
ci_set_secret_var APP_CLIENT_ID "$client_id"
ci_set_secret_var APP_CLIENT_SECRET "$client_secret"
echo "[DEBUG] CREATE CLIENT APPLICATION COMPLETE"
